method.description:
获取有关共享体素处理的调试信息。
返回的字典具有以下结构：
[codeblock]
{
	"thread_pools": {
		"general": {
			"tasks": int,
			"active_threads": int,
			"thread_count": int,
			"task_names": PackedStringArray
		}
	},
	"tasks": {
		"streaming": int,
		"meshing": int,
		"generation": int,
		"main_thread": int,
		"gpu": int
	},
	"memory_pools": {
		"voxel_used": int,
		"voxel_total": int,
		"block_count": int,
		"std_allocated": int,
		"std_deallocated": int,
		"std_current": int
	}
}
[/codeblock]
